package com.ecobridge.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="events") public class EcoEventEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="community_id") private Long communityId; @Column(name="created_by",nullable=false) private Long organizerId; @Column(name="title",nullable=false,length=200) private String name; @Column(columnDefinition="TEXT") private String description; @Column(name="event_date",nullable=false) private LocalDate date; @Column(name="start_time") private LocalTime startTime; @Column(name="end_time") private LocalTime endTime; @Column(nullable=false,length=255) private String location; @Column(name="event_type",length=80) private String eventType; private Integer capacity; @Column(name="image_url",columnDefinition="TEXT") private String imageUrl; @Column(nullable=false,length=30) private String status="UPCOMING"; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 @Transient private String organizer; @Transient private int registered;
 @PrePersist void create(){var n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();}
 public Long getId(){return id;} public Long getOrganizerId(){return organizerId;} public void setOrganizerId(Long v){organizerId=v;} public Long getCommunityId(){return communityId;} public void setCommunityId(Long v){communityId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public String getTime(){return startTime==null?null:startTime.toString();} public void setTime(String v){startTime=v==null||v.isBlank()?null:LocalTime.parse(v);} public String getLocation(){return location;} public void setLocation(String v){location=v;} public int getCapacity(){return capacity==null?0:capacity;} public void setCapacity(int v){capacity=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public String getOrganizer(){return organizer;} public void setOrganizer(String v){organizer=v;} public int getRegistered(){return registered;} public void setRegistered(int v){registered=v;}
}
